using Captovix;
using System.IO.Compression;
using System.Text;
int n=0;void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS: "+s);}void Reject(Action a,string s){try{a();}catch{Check(true,s);return;}throw new Exception("Accepted: "+s);}
var root=Path.Combine(Path.GetTempPath(),"Captovix-batch-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
try{
Check(BatchNaming.Safe("bad:/\\?*name. ")=="bad_____name","Windows filename sanitization independent of host OS");Check(BatchNaming.Safe("CON.txt")=="_CON.txt","Reserved device basename protected");Check(BatchNaming.Safe("...")=="Captovix","Empty dot basename receives default");Check(BatchNaming.Safe(new string('x',200)).Length==120,"Long name capped");Check(BatchNaming.Safe("Ảnh đã sửa")=="Ảnh đã sửa","Unicode titles retained");
var options=new BatchOptions();Check(BatchNaming.FileName(options,"Ảnh",DateTimeOffset.Now,3).EndsWith("-003-Ảnh.png"),"Filename token/index expansion");Check(BatchNaming.FileName(options with{Format="JPEG"},"Ảnh",DateTimeOffset.Now,3).EndsWith(".jpg"),"JPEG correct extension");Reject(()=>(options with{Format="WebP"}).Validate(),"Unimplemented format rejected");Reject(()=>(options with{NamePattern="{unknown}"}).Validate(),"Unknown template token rejected");Reject(()=>(options with{LongEdge=-1}).Validate(),"Negative resize rejected");Reject(()=>(options with{WatermarkSize=0}).Validate(),"Invalid watermark size rejected");
Check(BatchNaming.Size(3840,2160,1920)==(1920,1080),"Long edge keeps 16:9 dimensions");Check(BatchNaming.Size(120,80,1920)==(120,80),"No automatic upscaling");Check(BatchNaming.Size(381,99,0)==(381,99),"Native preset preserves exact pixels");Check(BatchNaming.Size(1,8000,1280)==(1,1280),"Very narrow resize never reaches zero");
var reserved=new HashSet<string>(StringComparer.OrdinalIgnoreCase);File.WriteAllText(Path.Combine(root,"sample.png"),"source");string planned=BatchNaming.Unique(root,"sample.png",reserved);Check(planned.EndsWith("sample (2).png"),"Collision adds suffix");Check(BatchNaming.Unique(root,"sample.png",reserved).EndsWith("sample (3).png"),"Planned jobs do not collide with each other");Check(File.ReadAllText(Path.Combine(root,"sample.png"))=="source","Planning leaves source untouched");
var all=Enumerable.Range(0,120).Select(i=>new Entry(i,DateTimeOffset.UnixEpoch.AddDays(i))).ToArray();var recent=RecentSelection.Select(all,e=>e.Date);Check(recent.Count==50&&recent[0].Id==119&&recent[^1].Id==70,"Only latest 50 occupy recent strip");Check(all.Length==120,"Older history retained");recent=RecentSelection.Select(all,e=>e.Date,all[0]);Check(recent.Count==50&&recent.Contains(all[0])&&recent[0].Id==119,"Opened history fits within 50 slots");Check(!RecentSelection.Select(all,e=>e.Date,new Entry(-1,DateTimeOffset.Now)).Any(e=>e.Id==-1),"Removed or foreign pin never returns");Check(RecentSelection.Select(Array.Empty<Entry>(),e=>e.Date).Count==0,"Empty library supported");Check(RecentSelection.Select(all.Concat(all),e=>e.Date).Distinct().Count()==50,"No duplicates in recent strip");Reject(()=>RecentSelection.Select(all,e=>e.Date,null,51),"Recent limit cannot exceed 50");
byte[] rgb=[255,0,0,255,0,0,255,0,0,0,0,255,0,0,255,0,0,255];var page=PdfImages.Encode(3,2,rgb);using(var z=new ZLibStream(new MemoryStream(page.DeflatedRgb),CompressionMode.Decompress)){using var output=new MemoryStream();z.CopyTo(output);Check(output.ToArray().SequenceEqual(rgb),"PDF image encoding preserves exact RGB pixels");}
string pdf=Path.Combine(root,"document.pdf");PdfImages.Write(pdf,[page,page with{Width=2,Height=3}]);byte[] bytes=File.ReadAllBytes(pdf);var text=Encoding.Latin1.GetString(bytes);Check(text.StartsWith("%PDF-1.4")&&text.Contains("/Count 2"),"PDF header and page count");Check(text.Contains("/MediaBox [0 0 842 595]")&&text.Contains("/MediaBox [0 0 595 842]"),"PDF orientation follows each image");Check(text.Contains("/Filter /FlateDecode")&&!text.Contains("DCTDecode"),"PDF stores lossless image data");Reject(()=>PdfImages.Write(pdf,[page]),"Existing PDF never overwritten");Check(File.ReadAllBytes(pdf).SequenceEqual(bytes),"Failed PDF overwrite preserves committed file");Reject(()=>PdfImages.Write(Path.Combine(root,"empty.pdf"),[]),"Empty PDF rejected");using(var cancel=new CancellationTokenSource()){cancel.Cancel();Reject(()=>PdfImages.Write(Path.Combine(root,"cancel.pdf"),[page],cancel.Token),"PDF supports cancellation");Check(!File.Exists(Path.Combine(root,"cancel.pdf"))&&!Directory.EnumerateFiles(root,"*.tmp").Any(),"Cancelled PDF has no partial final/temp file");}
if(args.Length>0){string fixture=args[0];if(File.Exists(fixture))File.Delete(fixture);PdfImages.Write(fixture,[page,page with{Width=2,Height=3}]);}
Console.WriteLine($"{n} batch/PDF/recent checks passed.");
}finally{Directory.Delete(root,true);}
record Entry(int Id,DateTimeOffset Date);
